WITH lines AS (SELECT id, service, host, log_ts, level, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, v), with_windows AS (SELECT *, ROW_NUMBER() OVER w_ordered row_seq FROM lines WINDOW w_ordered AS (PARTITION BY level ORDER BY log_ts DESC, id, attr_key)), cleaned AS (SELECT id, service, host, log_ts, attr_key, row_seq, CONCAT(level, ' ', host) level_host, COALESCE(attr_key, 'N/A') attr_key_clean FROM with_windows WHERE log_ts > TIMESTAMP '2025-06-01 08:00:00' AND log_ts < '2024-05-01'), metrics AS (SELECT *, MIN(row_seq) OVER (PARTITION BY attr_key ORDER BY row_seq, id, attr_key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_min_row_seq, SUM(row_seq) OVER (PARTITION BY attr_key ORDER BY row_seq, id, attr_key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_sum_row_seq, COUNT(row_seq) OVER (PARTITION BY attr_key ORDER BY row_seq, id, attr_key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_count_row_seq, AVG(row_seq) OVER (PARTITION BY attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) row_seq_avg_15m FROM cleaned WHERE service IN ('checkout', 'billing', 'auth')), scored AS (SELECT id, service, host, attr_key, row_seq, level_host, last7_sum_row_seq, last7_count_row_seq, row_seq_avg_15m, ROUND(row_seq / SUM(row_seq) OVER (PARTITION BY service), 4) row_seq_share, CUME_DIST() OVER (ORDER BY row_seq NULLS LAST) row_seq_cume_dist FROM metrics), summary AS (SELECT service, host, COUNT(*) FILTER (WHERE service = 'auth') AS auth_rows, SUM(last7_sum_row_seq) FILTER (WHERE host = 'h3') AS h3_total_last7_sum_row_seq, RANK() OVER (PARTITION BY service ORDER BY COUNT(*) FILTER (WHERE service = 'auth') DESC) AS auth_rows_rank FROM scored GROUP BY service, host) SELECT service, host, auth_rows, h3_total_last7_sum_row_seq, CASE WHEN host RLIKE '^(h3|h1)$' THEN 'CORE' WHEN host RLIKE '^(h2|h4)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS host_zone FROM summary ORDER BY host DESC, host_zone DESC;
